cypress_script:
describe('Sortable Data Tables', () => {
  it('should display sortable data tables correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('h3').contains('Data Tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table2').should('be.visible');
  });

  it('should not navigate away on invalid action', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/tables');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Sortable Data Tables', () => {
  test('should display sortable data tables correctly', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await expect(page.locator('h3')).toHaveText('Data Tables');
    await expect(page.locator('#table1')).toBeVisible();
    await expect(page.locator('#table2')).toBeVisible();
  });

  test('should not navigate away on invalid action', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/tables');
  });
});
